import React from 'react';
import { FieldsetProps } from '.';
declare const _default: any;
export default _default;
export declare const Default: {
    render: any;
    args: {
        legend: string;
        children: string;
    };
};
export declare const VisuallyHiddenLegend: {
    render: any;
    args: {
        legend: string;
        visuallyHiddenLegend: boolean;
        children: string;
    };
};
export declare const AsDiv: {
    render: any;
    args: {
        as: string;
        legend: string;
        children: string;
    };
};
export declare const WithCheckboxes: {
    render: (args: FieldsetProps) => React.JSX.Element;
    args: {
        legend: string;
    };
};
export declare const WithRadios: {
    render: (args: FieldsetProps) => React.JSX.Element;
    args: {
        legend: string;
        legendId: string;
    };
};
export declare const Inverse: {
    render: (args: FieldsetProps) => React.JSX.Element;
    args: {
        legend: string;
    };
};
